const batch = $input.first().json;
const config = $('Configuration').first().json;
const fail = (message) => { throw new Error(message); };
const isString = (v) => typeof v === 'string' && v.trim().length > 0;
if (batch.schema_version !== 'jery-log-candidates-v1') fail('Unsupported batch schema');
if (batch.consumer !== config.consumer) fail('Consumer mismatch');
if (!isString(batch.batch_id) || !isString(batch.next_cursor)) fail('Missing batch identity/cursor');
if (batch.sanitized !== true) fail('Collector must sanitize data before returning it');
if (!Array.isArray(batch.examples) || batch.examples.length > config.limit) fail('Invalid batch size');
const ids = new Set();
const examples = batch.examples.map((r) => {
  if (!isString(r.id) || ids.has(r.id)) fail('Missing or duplicate example ID');
  ids.add(r.id);
  if (!isString(r.session_group) || !isString(r.request) || !isString(r.tool_catalog_version)) fail('Missing example metadata');
  if (r.source !== 'hermes_log') fail('Expected real log source');
  if (!Array.isArray(r.context) || r.context.some(m => !['user', 'assistant', 'tool'].includes(m.role) || typeof m.content !== 'string')) fail('Invalid prior context');
  if (!Array.isArray(r.candidate_tools) || r.candidate_tools.some(t => !isString(t)) || new Set(r.candidate_tools).size !== r.candidate_tools.length) fail('Invalid candidates');
  if (typeof r.candidate_tools_reconstructed !== 'boolean') fail('Missing candidate provenance');
  if (!Array.isArray(r.observed_choices)) fail('Missing observed choices');
  const observed = r.observed_choices.map(c => {
    if (!isString(c.tool) || !r.candidate_tools.includes(c.tool)) fail('Observed tool missing from candidate catalog');
    if (c.action !== undefined && !isString(c.action)) fail('Invalid observed action');
    return {tool: c.tool, ...(c.action !== undefined ? {action: c.action} : {})};
  });
  if (!['unknown', 'ok', 'error', 'mixed'].includes(r.outcome)) fail('Invalid execution outcome');
  return {
    id: r.id, session_group: r.session_group, request: r.request,
    context: r.context.map(m => ({role: m.role, content: m.content})),
    candidate_tools: r.candidate_tools, tool_catalog_version: r.tool_catalog_version,
    candidate_tools_reconstructed: r.candidate_tools_reconstructed,
    observed_choices: observed, outcome: r.outcome, source: 'hermes_log',
    decision: null, acceptable_choices: [], review_status: 'needs_human_review'
  };
});
// Empty batches are also acknowledged, allowing filtered records to advance the cursor.
return [{json: {
  schema_version: batch.schema_version, consumer: batch.consumer,
  batch_id: batch.batch_id, next_cursor: batch.next_cursor, examples
}}];

const receipt = $input.first().json;
const submitted = $('Validate Review Candidates').first().json;
if (receipt.batch_id !== submitted.batch_id || receipt.next_cursor !== submitted.next_cursor || receipt.committed !== true) {
  throw new Error('Review batch persistence/checkpoint was not confirmed');
}
return [{json: {batch_id: receipt.batch_id, committed: true, candidate_count: submitted.examples.length}}];
